-- Real Supabase integration: all fixtures and storage metadata roll back.
begin;
insert into auth.users(id) values('a4444444-4444-4444-8444-444444444444'),('b4444444-4444-4444-8444-444444444444');
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{"sub":"a4444444-4444-4444-8444-444444444444"}',true);
select public.kiyi_command('bundle');
create temporary table media_fixture(mime text,path text);
do $$declare mime text;p text;begin
 foreach mime in array array['image/png','video/mp4'] loop
 p=public.kiyi_media_worker('reserve',jsonb_build_object('owner','a4444444-4444-4444-8444-444444444444','mime',mime,'bytes',128))->>'path';
 insert into storage.objects(bucket_id,name,metadata) values('kiyi-media',p,jsonb_build_object('size',128,'mimetype',mime));
 perform public.kiyi_media_worker('confirm',jsonb_build_object('path',p));
 insert into media_fixture values(mime,p);
 end loop;
end$$;
grant select on media_fixture to authenticated;
set local role authenticated;
do $$declare x jsonb;r jsonb;car uuid;bike uuid;t uuid;photo uuid;video uuid;img text;movie text;rid uuid=gen_random_uuid();bad boolean;begin
 select path into img from media_fixture where mime='image/png';select path into movie from media_fixture where mime='video/mp4';
 perform public.kiyi_command('profile','{"username":"stage4_a","searchable":true}');
 x=public.kiyi_command('vehicle_create','{"model":"peugeot-208","plate":"07 SCL 401"}');car=(x->>'id')::uuid;
 x=public.kiyi_command('vehicle_create','{"model":"honda-pcx-125","plate":"07 SCL 402"}');bike=(x->>'id')::uuid;
 perform public.kiyi_command('vehicle_update',jsonb_build_object('vehicle_id',car,'visibility','public'));
 perform public.kiyi_command('vehicle_update',jsonb_build_object('vehicle_id',bike,'visibility','public'));
 bad=false;begin perform public.kiyi_command('post_create','{"text":"   "}');exception when raise_exception then bad=true;end;assert bad,'Blank accepted';
 x=public.kiyi_command('post_create',jsonb_build_object('text','Metin','location','Antalya','request_id',rid));t=(x->'post'->>'id')::uuid;
 x=public.kiyi_command('post_create',jsonb_build_object('text','Metin','location','Antalya','request_id',rid));assert (x->>'replayed')::boolean and x->'post'->>'id'=t::text,'Duplicate submission';
 x=public.kiyi_command('post_create',jsonb_build_object('media',img,'vehicle_id',car));photo=(x->'post'->>'id')::uuid;assert x->'post'->'vehicle'->>'id'=car::text and not(x->'post'?'vehicle_id'),'Unsafe/missing vehicle tag';
 x=public.kiyi_command('post_create',jsonb_build_object('media',movie,'vehicle_id',bike));video=(x->'post'->>'id')::uuid;
 perform public.kiyi_command('post_create','{"text":"Takipçilere","visibility":"followers"}');
 x=public.kiyi_command('posts','{"filter":"photo"}');assert jsonb_array_length(x->'posts')=1 and x->'posts'->0->>'id'=photo::text,'Photo filter';
 x=public.kiyi_command('posts','{"filter":"video"}');assert jsonb_array_length(x->'posts')=1 and x->'posts'->0->>'id'=video::text,'Video filter';
 x=public.kiyi_command('posts','{"filter":"car"}');assert jsonb_array_length(x->'posts')=1,'Car filter';
 x=public.kiyi_command('posts','{"filter":"motorcycle"}');assert jsonb_array_length(x->'posts')=1,'Motorcycle filter';
 x=public.kiyi_command('posts','{"limit":2}');assert jsonb_array_length(x->'posts')=2 and x->'next' is not null,'Page one';
 r=public.kiyi_command('posts',jsonb_build_object('limit',2,'cursor',x->'next'));assert jsonb_array_length(r->'posts')=2,'Page two';assert not exists(select 1 from jsonb_array_elements(r->'posts')b join jsonb_array_elements(x->'posts')a on a->>'id'=b->>'id'),'Page duplicates';
 x=public.kiyi_command('post_edit',jsonb_build_object('id',t,'version',1,'text','Düzenlendi'));assert x->'post'->>'text'='Düzenlendi' and (x->'post'->>'version')::int=2,'Edit';
 bad=false;begin perform public.kiyi_command('post_edit',jsonb_build_object('id',t,'version',1,'text','Stale'));exception when sqlstate 'PT409' then bad=true;end;assert bad,'Stale edit did not return HTTP conflict';
 bad=false;begin perform public.kiyi_command('post_edit',jsonb_build_object('id',t,'version',2,'location','36.1,30.2'));exception when raise_exception then bad=true;end;assert bad,'GPS accepted';
 perform set_config('request.jwt.claims','{"sub":"b4444444-4444-4444-8444-444444444444"}',true);
 x=public.kiyi_command('posts','{"author":"a4444444-4444-4444-8444-444444444444"}');assert jsonb_array_length(x->'posts')=3,'Profile visibility';
 x=public.kiyi_command('posts','{"filter":"following"}');assert jsonb_array_length(x->'posts')=0,'Following leak';
 bad=false;begin perform public.kiyi_command('post_edit',jsonb_build_object('id',t,'version',2,'text','Stolen'));exception when insufficient_privilege then bad=true;end;assert bad,'Foreign edit';
 bad=false;begin perform public.kiyi_command('post_delete',jsonb_build_object('id',t));exception when raise_exception then bad=true;end;assert bad,'Foreign deletion';
 bad=false;begin perform public.kiyi_command('post_create',jsonb_build_object('text','Stolen car','vehicle_id',car));exception when insufficient_privilege then bad=true;end;assert bad,'Foreign vehicle';
 bad=false;begin perform public.kiyi_command('post_create',jsonb_build_object('media',img));exception when insufficient_privilege then bad=true;end;assert bad,'Foreign media';
 bad=false;begin update public.kiyi_posts set text='Attack' where id=t;exception when insufficient_privilege then bad=true;end;assert bad,'Direct write';
 perform public.kiyi_command('follow','{"target":"a4444444-4444-4444-8444-444444444444","enabled":true}');
 x=public.kiyi_command('posts','{"filter":"following"}');assert jsonb_array_length(x->'posts')=4,'Following feed';
 x=public.kiyi_command('like',jsonb_build_object('id',t,'like',true));assert (x->'post'->>'likes')::int=1,'Like';
 x=public.kiyi_command('comment',jsonb_build_object('id',t,'text','Merhaba'));assert (x->'post'->>'commentCount')::int=1 and jsonb_array_length(x->'post'->'comments')=1,'Comments';
 perform public.kiyi_command('post_report',jsonb_build_object('id',t,'reason','Spam','details','Test fixture'));
 x=public.kiyi_command('post_vehicle',jsonb_build_object('id',photo));assert x->'vehicle'->>'plate'='07 SCL 401','Visible vehicle';
 perform set_config('request.jwt.claims','{"sub":"a4444444-4444-4444-8444-444444444444"}',true);
 perform public.kiyi_command('vehicle_update',jsonb_build_object('vehicle_id',car,'visibility','private'));
 perform set_config('request.jwt.claims','{"sub":"b4444444-4444-4444-8444-444444444444"}',true);
 x=public.kiyi_command('post_get',jsonb_build_object('id',photo));assert x->'post'->'vehicle'='null'::jsonb and (x->'post'->>'vehicleHidden')::boolean and not(x->'post'->'profile'?'plate'),'Private plate leak';
 bad=false;begin perform public.kiyi_command('post_vehicle',jsonb_build_object('id',photo));exception when insufficient_privilege then bad=true;end;assert bad,'Private detail leak';
 perform set_config('request.jwt.claims','{"sub":"a4444444-4444-4444-8444-444444444444"}',true);
 perform public.kiyi_command('sharing','{"ghost":true}');
 perform set_config('request.jwt.claims','{"sub":"b4444444-4444-4444-8444-444444444444"}',true);
 x=public.kiyi_command('posts');assert jsonb_array_length(x->'posts')=0,'Ghost identity leak';
 perform set_config('request.jwt.claims','{"sub":"a4444444-4444-4444-8444-444444444444"}',true);
 perform public.kiyi_command('sharing','{"ghost":false}');
 perform public.kiyi_command('post_edit',jsonb_build_object('id',photo,'version',1,'text','Medya kaldırıldı','media',null));
 perform public.kiyi_command('post_delete',jsonb_build_object('id',video));perform public.kiyi_command('post_delete',jsonb_build_object('id',t));
 x=public.kiyi_command('posts','{"author":"a4444444-4444-4444-8444-444444444444"}');assert jsonb_array_length(x->'posts')=2,'Deleted posts visible';
 perform set_config('request.jwt.claims','{"sub":"b4444444-4444-4444-8444-444444444444"}',true);
 perform public.kiyi_command('block','{"target":"a4444444-4444-4444-8444-444444444444","enabled":true}');
 x=public.kiyi_command('posts');assert jsonb_array_length(x->'posts')=0,'Blocked posts leaked';
end$$;
reset role;
do $$declare x jsonb;keep_id uuid=gen_random_uuid();image_path text;begin
 assert (select count(*) from kiyi_private.media_cleanup c join media_fixture m on m.path=c.path)=2,'Media queue missing';
 select path into image_path from media_fixture where mime='image/png';
 insert into public.kiyi_posts(id,author,text,media,created,visibility) values(keep_id,'a4444444-4444-4444-8444-444444444444','Retained reference',image_path,0,'public');
 x=public.kiyi_media_worker('cleanup',jsonb_build_object('secret',(select secret from kiyi_private.media_worker_secret)));
 assert not(x->'paths'?image_path),'Referenced media deleted';
 delete from public.kiyi_posts where id=keep_id;
 x=public.kiyi_media_worker('cleanup',jsonb_build_object('secret',(select secret from kiyi_private.media_worker_secret)));
 assert (select count(*) from media_fixture where x->'paths'?path)=2,'Orphan cleanup';
 assert (select count(*) from public.kiyi_reports where reporter='b4444444-4444-4444-8444-444444444444')=1,'Report missing';
 assert not exists(select 1 from information_schema.role_table_grants where table_name='kiyi_posts' and grantee in ('anon','authenticated') and privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')),'Unsafe grants';
end$$;
select 'PASS stage4: media, edit, delete, tags, six filters, pagination, profile, social actions, privacy, cleanup, cross-user isolation' as result;
rollback;
